LobbyModel = {};
local this = LobbyModel;

this.enterGameData = {};---enter时需要带给服务器的数据
this.selectDeckType = 0;
this.homeForLobby = 0;

this.newHeroData = Dictionary:New();
this.newCardData = Dictionary:New();

function LobbyModel.SetEnterGameData(data)
    this.enterGameData = data;
end

---
---加载武将图片,避免因异步加载造成的重复加载问题
---计数判断有没有加载完成,如果出现加载数目不对或者资源错误则会无法进入页面引发严重问题,需要后期想解决方案
---
function LobbyModel.LoadHeroPic(callback)
    if this.heroPicList == nil then
        this.heroPicList = {}
    end
    local num = 0;
    local useLoad = false;---用来判断是否需要加载新资源
    HeroManager.ForEachHeroData(function(hero)
        if hero.hide == false then
            if this.heroPicList[hero.data.Image] == nil then
                useLoad = true;
                ---此处置为0是为了不让foreach在加载同一图片的过程中再次加载相同资源，避免异步加载带来的问题
                this.heroPicList[hero.data.Image] = 0;
                num = num + 1;
                local image = string.format("hero_body_%d", hero.data.Image);
                TextureSystem.Instance:LoadTexture2DX(image,TextureManager.TextureGroup.Card, function (texture2D)
                    this.heroPicList[hero.data.Image] = texture2D;
                    num = num - 1;
                    if num == 0 then
                    end
                end);
            end
        end
    end)
    ---不需要加载新资源时直接调用回调
    if useLoad == false then
        if callback ~= nil then
            callback();
        end
    end
end

---
---添加新获得的武将
---
function LobbyModel.AddNewHero(heroId)
    local hero = HeroManager.GetHero(heroId);
    if hero ~= nil then
        hero:PopNew(true);
    end
    this.newHeroData:Add(heroId, hero);
end

---
---删除新获得的武将
---
function LobbyModel.RemoveNewHero(heroId)
    local hero = HeroManager.GetHero(heroId);
    if hero ~= nil then
        hero:PopNew(false);
    end
    this.newHeroData:Remove(heroId);
end

function LobbyModel.ClearNewHero()
    this.newHeroData:ForEachValue(function(hero)
        hero:PopNew(false);
    end);
end

---
---添加新获得的卡牌
---
function LobbyModel.AddNewCard(cardId)
    local card = CardManager.Card(cardId);
    if card ~= nil then
        card:PopNew(true);
    end
    this.newCardData:Add(cardId, card);
end

---
---删除新获得的卡牌
---
function LobbyModel.RemoveNewCard(cardId)
    local card = CardManager.Card(cardId);
    if card ~= nil then
        card:PopNew(false);
    end
    this.newCardData:Remove(cardId);
end

function LobbyModel.ClearNewCard()
    this.newCardData:ForEachValue(function(card)
        card:PopNew(false);
    end);
end